module sequence_101(input clk, rst, din, output reg hit);
  reg prev1, prev2;
  reg [1:0] cnt;
  always @(posedge clk) begin
    if (rst) begin
      prev1 <= 1'b0;
      prev2 <= 1'b0;
      cnt   <= 2'd0;
      hit   <= 1'b0;
